// Shared B2B department constants, types and the Supabase escape-hatch.
//
// Mirrors src/lib/crm.ts (STAGES / SOURCES / SERVICES as {id,label,color} plus
// labelFor/initials helpers) for the new B2B department. Everything the B2B
// pages share — lead statuses, pipeline stages, sources, firm metadata, partner
// health, referral statuses and activity types — lives here so no page
// hardcodes its own copy.
//
// B2B business tables are NOT in src/integrations/supabase/types.ts: that file
// is generated by `supabase gen types`, which needs project credentials we do
// not have in the sandbox. So, exactly like src/lib/hrms.ts' hrmsDb(), B2B
// queries go through b2bDb() (a `supabase as any` cast) and the hand-written
// row types below are the contract. The row types are added as the tables land
// in later phases; for now this module carries the constants and the helper.

import { supabase } from "@/integrations/supabase/client";

/**
 * Supabase client cast to `any` for B2B tables only.
 *
 * Narrow escape hatch, deliberately named so it is obvious at every call site
 * that these queries are unchecked against the generated schema — the B2B row
 * types (filled in as tables are added) are the contract instead.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const b2bDb = () => supabase as any;

// ---------------------------------------------------------------------------
// Hand-written B2B row types.
//
// These mirror the columns in supabase/migrations/20260517000002_b2b_core.sql
// exactly and are the contract for every B2B query, because the generated
// src/integrations/supabase/types.ts cannot be regenerated in the sandbox (no
// Supabase credentials) and therefore does not contain these tables. `numeric`
// columns can come back from PostgREST as either number or string, so they are
// typed `number | string` like the HRMS row types.
// ---------------------------------------------------------------------------

