// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** {id,label}[] lookup — returns the label for an id, or the id, or a dash. */
export function labelFor<T extends { id: string; label: string }>(
  arr: readonly T[],
  id: string | null | undefined,
) {
  return arr.find((x) => x.id === id)?.label ?? id ?? "—";
}

/**
 * 1-based position of a pipeline stage, or 0 when the id is not a forward
 * pipeline stage (e.g. a closed/lost outcome). Pure so it is unit-testable.
 */
export function pipelineStageOrder(id: string | null | undefined): number {
  return B2B_PIPELINE_STAGES.find((s) => s.id === id)?.order ?? 0;
}

/** True when `id` is one of the closed / lost outcomes (not in the board). */
export function isClosedOutcome(id: string | null | undefined): boolean {
  return B2B_CLOSED_OUTCOMES.some((o) => o.id === id);
}
